    Q("itv3q168", "itv-rbac", "Wem kann man laut Folie eine Rolle zuweisen?", "Einem Benutzer, einer Gruppe oder einem Service Principal", ["Nur Regionen", "Nur Resource Groups", "Nur Tags"], ""),
    TF("itv3q169", "itv-rbac", "Azure-RBAC-Rollen und Microsoft-Entra-Rollen sind zwei getrennte Rollensysteme.", true, "Review-Frage 8."),
    TF("itv3q170", "itv-rbac", "Eine RBAC-Rolle auf einer Resource Group gilt automatisch auch für die übergeordnete Subscription.", false, "Vererbung läuft nur nach unten."),
    TF("itv3q171", "itv-rbac", "Der Contributor darf Zugriff an andere Benutzer vergeben.", false, "Das darf nur der Owner (bzw. User Access Administrator).")
